import { useId, type ReactNode } from 'react';

export interface ModelIconProps {
  name: string;
  size?: number;
  className?: string;
  fallback?: ReactNode;
}

export function normalizeIconKey(name: string): string {
  const n = name.toLowerCase().trim();
  if (n.includes('openai') || n.includes('chatgpt') || n.startsWith('gpt-')) return 'openai';
  if (n.includes('anthropic') || n.includes('claude')) return 'anthropic';
  if (n.includes('gemini') || n.includes('google')) return 'gemini';
  if (n.includes('deepseek')) return 'deepseek';
  if (n.includes('groq')) return 'groq';
  if (n.includes('cerebras')) return 'cerebras';
  if (n.includes('kimi') || n.includes('moonshot')) return 'kimi';
  if (n.includes('qwen') || n.includes('alibaba') || n.includes('tongyi') || n.includes('dashscope')) return 'qwen';
  if (n.includes('openrouter')) return 'openrouter';
  if (n.includes('ollama')) return 'ollama';
  if (n.includes('union')) return 'union';
  if (n === 'custom') return 'custom';
  return '';
}

